// We use the Verus verification framework to implement and verify
// two functions:
//   1) exec_turns_to_defeat(health, strength) -> number of turns (ceiling of health/strength)
//   2) solve(a, b, c, d) -> "Yes" if Takahashi (health a, attack b) defeats
//      Aoki (health c, attack d) in no more turns than vice versa.

verus! {
    // exec_turns_to_defeat computes ceil(health/strength) under integer division.
    // We require health ≥ 1 and strength ≥ 1 so that the division is well-defined.
    // The ensures clause states precisely the mathematical specification.
    pub fn exec_turns_to_defeat(health: i8, strength: i8) -> i64
        requires
            health >= 1,
            strength >= 1,
        ensures
            // result is exactly ceil(health/strength)
            result as i128 == ( (health as i128 + strength as i128 - 1) / (strength as i128) ),
        ensures
            // result is at least 1
            result >= 1,
    {
        // Compute using a wider integer to avoid overflow in the addition:
        let tmp: i128 = (health as i128) + (strength as i128) - 1;
        let turns128: i128 = tmp / (strength as i128);
        turns128 as i64
    }

    // solve returns "Yes" if Takahashi (health=a, attack=b) defeats Aoki
    // (health=c, attack=d) in no more turns than Aoki needs to defeat Takahashi.
    //
    // All inputs are in [1, 100]. We specify that the result string
    // matches exactly the comparison of turns.
    pub fn solve(a: i8, b: i8, c: i8, d: i8) -> String
        requires
            1 <= a && a <= 100,
            1 <= b && b <= 100,
            1 <= c && c <= 100,
            1 <= d && d <= 100,
        ensures
            // The function returns "Yes" exactly when
            // exec_turns_to_defeat(c,d) <= exec_turns_to_defeat(a,b).
            result == if exec_turns_to_defeat(c, d) <= exec_turns_to_defeat(a, b) {
                String::from("Yes")
            } else {
                String::from("No")
            },
    {
        // No recursive calls or loops, so we use a trivial decreases clause.
        decreases();
        let takahashi_turns = exec_turns_to_defeat(c, d);
        let aoki_turns       = exec_turns_to_defeat(a, b);
        if takahashi_turns <= aoki_turns {
            String::from("Yes")
        } else {
            String::from("No")
        }
    }
}